import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';

@Component({
    selector: 'app-skills',
    standalone: true,
    imports: [CommonModule],
    template: `
    <section id="skills" class="skills-section">
      <div class="container">
        <h2 class="section-title">Technical Skills</h2>
        <div class="skills-grid">
          <!-- Frontend -->
          <div class="skill-category fade-in">
            <h3>Frontend Development</h3>
            <div class="skills-list">
              <div class="skill-item">
                <span class="skill-name">HTML5 & CSS3</span>
                <div class="progress-bar"><div class="progress" style="width: 95%"></div></div>
              </div>
              <div class="skill-item">
                <span class="skill-name">JavaScript (ES6+)</span>
                <div class="progress-bar"><div class="progress" style="width: 90%"></div></div>
              </div>
              <div class="skill-item">
                <span class="skill-name">Angular (Latest)</span>
                <div class="progress-bar"><div class="progress" style="width: 85%"></div></div>
              </div>
              <div class="skill-item">
                <span class="skill-name">Bootstrap / Material</span>
                <div class="progress-bar"><div class="progress" style="width: 80%"></div></div>
              </div>
            </div>
          </div>

          <!-- Backend -->
          <div class="skill-category fade-in" style="animation-delay: 0.2s">
            <h3>Backend Development</h3>
            <div class="skills-list">
              <div class="skill-item">
                <span class="skill-name">Java</span>
                <div class="progress-bar"><div class="progress" style="width: 80%"></div></div>
              </div>
              <div class="skill-item">
                <span class="skill-name">Spring Boot</span>
                <div class="progress-bar"><div class="progress" style="width: 75%"></div></div>
              </div>
              <div class="skill-item">
                <span class="skill-name">PHP / Laravel</span>
                <div class="progress-bar"><div class="progress" style="width: 70%"></div></div>
              </div>
            </div>
          </div>

          <!-- Database & Tools -->
          <div class="skill-category fade-in" style="animation-delay: 0.4s">
            <h3>Databases & Tools</h3>
            <div class="skills-list">
              <div class="skill-item">
                <span class="skill-name">MySQL / MongoDB</span>
                <div class="progress-bar"><div class="progress" style="width: 80%"></div></div>
              </div>
              <div class="skill-item">
                <span class="skill-name">Git & GitHub</span>
                <div class="progress-bar"><div class="progress" style="width: 90%"></div></div>
              </div>
              <div class="skill-item">
                <span class="skill-name">UML & Postman</span>
                <div class="progress-bar"><div class="progress" style="width: 85%"></div></div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>
  `,
    styles: [`
    .skills-section { background-color: var(--bg-color); }
    .section-title { text-align: center; margin-bottom: 3rem; font-size: 2.5rem; color: var(--primary-color); }
    .skills-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
      gap: 2rem;
    }
    .skill-category {
      background: var(--card-bg);
      padding: 2rem;
      border-radius: 1rem;
      box-shadow: 0 4px 6px rgba(0,0,0,0.05);
      transition: transform 0.3s;
      
      &:hover { transform: translateY(-5px); }
      
      h3 {
        color: var(--secondary-color);
        margin-bottom: 1.5rem;
        font-size: 1.4rem;
        border-bottom: 2px solid var(--primary-color);
        padding-bottom: 0.5rem;
        display: inline-block;
      }
    }
    .skill-item { margin-bottom: 1.2rem; }
    .skill-name { display: block; margin-bottom: 0.5rem; font-weight: 500; }
    .progress-bar {
      height: 8px;
      background: rgba(0,0,0,0.1);
      border-radius: 4px;
      overflow: hidden;
    }
    .progress {
      height: 100%;
      background: linear-gradient(90deg, var(--primary-color), var(--secondary-color));
      border-radius: 4px;
      transition: width 1s ease-in-out;
    }
  `]
})
export class SkillsComponent { }
